import{_ as o,o as a,c as t,a2 as r}from"./chunks/framework.CqdVOxXJ.js";const m=JSON.parse('{"title":"Corporate & government jobs","description":"","frontmatter":{},"headers":[],"relativePath":"desk/corporate-jobs.md","filePath":"desk/corporate-jobs.md","lastUpdated":1794643263000}'),n={name:"desk/corporate-jobs.md"};function s(i,e,h,l,p,d){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="corporate-government-jobs" tabindex="-1">Corporate &amp; government jobs <a class="header-anchor" href="#corporate-government-jobs" aria-label="Permalink to &quot;Corporate &amp; government jobs&quot;">​</a></h1><p><strong>Who:</strong> Owner or admin · <strong>Adds to:</strong> the <a href="/rakkii-cars-guide/desk/job/01-open-a-job">8 job steps</a></p><p>Companies, government offices and bidding jobs usually pay <strong>on terms</strong> against a <strong>PO</strong> (purchase order), so the car can leave before the money arrives.</p><h2 id="what-s-different-from-a-normal-job" tabindex="-1">What&#39;s different from a normal job <a class="header-anchor" href="#what-s-different-from-a-normal-job" aria-label="Permalink to &quot;What&#39;s different from a normal job&quot;">​</a></h2><h3 id="_1-set-up-the-company-once" tabindex="-1">1. Set up the company once <a class="header-anchor" href="#_1-set-up-the-company-once" aria-label="Permalink to &quot;1. Set up the company once&quot;">​</a></h3><p>In <strong>Workshop › Customers</strong>, add the company with its TIN, billing address and <strong>Credit terms (days)</strong>. For a PO that covers many jobs, create it in <strong>Finance › Blanket POs</strong>.</p><h3 id="_2-open-the-job" tabindex="-1">2. Open the job <a class="header-anchor" href="#_2-open-the-job" aria-label="Permalink to &quot;2. Open the job&quot;">​</a></h3><p>On <strong>New job</strong>, set <strong>Nature</strong> to Corporate, Government or Bidding, and pick the company and car.</p><h3 id="_3-record-the-po" tabindex="-1">3. Record the PO <a class="header-anchor" href="#_3-record-the-po" aria-label="Permalink to &quot;3. Record the PO&quot;">​</a></h3><p>On the <strong>Pay</strong> tab, card <strong>Nature and PO</strong>: enter the <strong>PO number</strong>, <strong>Approved PO amount</strong> and <strong>PO approved on</strong>, then <strong>Save</strong>.</p><h3 id="_4-upload-the-paperwork" tabindex="-1">4. Upload the paperwork <a class="header-anchor" href="#_4-upload-the-paperwork" aria-label="Permalink to &quot;4. Upload the paperwork&quot;">​</a></h3><p>Your shop may require documents before work starts (a PO, BAC resolution or notice of award). Upload them on the <strong>Files</strong> tab with the right <strong>Kind</strong>. The job tells you what&#39;s missing.</p><p>Owner only: to start without them, open <strong>Start work without the usual documents</strong> on the <strong>Files</strong> tab and save a reason.</p><h3 id="_5-repair-and-bill-as-usual" tabindex="-1">5. Repair and bill as usual <a class="header-anchor" href="#_5-repair-and-bill-as-usual" aria-label="Permalink to &quot;5. Repair and bill as usual&quot;">​</a></h3><p>Assign, start work, QC, then <strong>Bill customer ₱…</strong>. The invoice prints in the company&#39;s name. If a withholding percent applies, the <strong>Summary</strong> shows the expected net. Record the amount that actually arrives.</p><h3 id="_6-release-on-terms" tabindex="-1">6. Release on terms <a class="header-anchor" href="#_6-release-on-terms" aria-label="Permalink to &quot;6. Release on terms&quot;">​</a></h3><p>Once the customer invoice is <strong>posted</strong>, the car can be released without payment: &quot;Can the car leave?&quot; shows the balance as on credit terms. The open balance moves to <strong>Finance › Who owes us</strong> with its due date.</p><div class="warning custom-block"><p class="custom-block-title">No invoice, no release on terms</p><p>Without a posted invoice the normal hold applies. Bill first.</p></div><p>More detail: <a href="/rakkii-cars-guide/reference/07-lane-3-corporate-government-bidding-blanket-pos">Corporate, government &amp; blanket POs (reference)</a> and <a href="/rakkii-cars-guide/reference/08-lane-4-billing-chain-receivables-storage-credit-notes">Billing, receivables &amp; credit notes</a>.</p>',19)])])}const g=o(n,[["render",s]]);export{m as __pageData,g as default};
